 96 |     /*//////////////////////////////////////////////////////////////
 97 |                                CONSTRUCTOR
 98 |     //////////////////////////////////////////////////////////////*/
 99 | 
100 |     /// @notice Sets the owner address, the delegated address.
101 |     /// @param ownerAddress Address of contract deployer.
102 |     /// @param delegatedAddress Address of delegated signer for messages.
103 |     /// @param treasuryAddress_ Community treasury address.
104 |     constructor(address ownerAddress, address delegatedAddress, address treasuryAddress_)
105 |         ERC721("AI Arena Fighter", "FTR")
106 |     {
107 |         _ownerAddress = ownerAddress;
108 |         _delegatedAddress = delegatedAddress;
109 |         treasuryAddress = treasuryAddress_;
110 |         numElements[0] = 3;
111 |     } 
112 | 
113 |     /*//////////////////////////////////////////////////////////////
114 |                             EXTERNAL FUNCTIONS
115 |     //////////////////////////////////////////////////////////////*/
116 | 
117 |     /// @notice Transfers ownership from one address to another.
118 |     /// @dev Only the owner address is authorized to call this function.
119 |     /// @param newOwnerAddress The address of the new owner
120 |     function transferOwnership(address newOwnerAddress) external {
121 |         require(msg.sender == _ownerAddress);
122 |         _ownerAddress = newOwnerAddress;
123 |     }
124 | 
125 |     /// @notice Increase the generation of the specified fighter type.
126 |     /// @dev Only the owner address is authorized to call this function.
127 |     /// @param fighterType Type of fighter either 0 or 1 (champion or dendroid).
128 |     /// @return Generation count of the fighter type.
129 |     function incrementGeneration(uint8 fighterType) external returns (uint8) {
130 |         require(msg.sender == _ownerAddress);
131 |         generation[fighterType] += 1;
132 |         maxRerollsAllowed[fighterType] += 1;
133 |         return generation[fighterType];
134 |     }
